local BaseEffect = import('Game.Chapter.NewChapterEffect.BaseEffect')
local base = BaseEffect
local ImageComp = CS.UnityEngine.UI.Image
local KTool = CS.Engine.Lib.KTool
local cs_coroutine = require 'XLua.cs_coroutine'
---@class FadeInScreenEffect : BaseEffect
local FadeInScreenEffect = Class("FadeInScreenEffect", BaseEffect)

local NewChapterConstants = import("Game.Chapter.NewChapterConstants")
local DurationConfig = {
    [NewChapterConstants.ScreenEffect.WhiteFadeIn] = 3,
    [NewChapterConstants.ScreenEffect.WhiteFadeOut] = 3,
    [NewChapterConstants.ScreenEffect.RedFadeIn] = 2,
}

function FadeInScreenEffect:__init()
    self.TargetColor = nil
    self.StartColor = nil
    self.Duration = 0.75
    self.PrevColor = nil
    self.Tween = nil
    self._isFinish = nil
    self._isIn = nil
end

function FadeInScreenEffect:__delete()
    self.TargetColor = nil
    self.StartColor = nil
    self.Duration = nil
    self.PrevColor = nil
    self.Tween = nil
    self._isFinish = nil
    self._isIn = nil
end

---@param parameters NewChapter2DVo
function FadeInScreenEffect:Initialize(parameters)
    base.Initialize(self, parameters)
    if parameters.screenAnim == NewChapterConstants.ScreenEffect.RedFadeIn then
        self.TargetColor = Color.New(1,0,0,1)
        self.StartColor = Color.New(1,0,0,0)
        self._isIn = true
    elseif parameters.screenAnim == NewChapterConstants.ScreenEffect.BlackFadeIn then
        self.TargetColor = Color.New(0,0,0,1)
        self.StartColor = Color.New(0,0,0,0)
        self._isIn = true
    elseif parameters.screenAnim == NewChapterConstants.ScreenEffect.WhiteFadeIn then
        self.TargetColor = Color.New(1,1,1,1)
        self.StartColor = Color.New(1,1,1,0)
        self._isIn = true
    elseif parameters.screenAnim == NewChapterConstants.ScreenEffect.WhiteFadeOut then
        self.TargetColor = Color.New(1,1,1,0)
        self.StartColor = Color.New(1,1,1,1)
        self._isIn = false
    end

    if DurationConfig[parameters.screenAnim] then
        self.Duration = DurationConfig[parameters.screenAnim]
    end
end

function FadeInScreenEffect:StartEffect(object)
    base.StartEffect(self, object)

    if not KTool.IsActiveInHierarchy(object.gameObject) then
        KTool.SetActive(object.gameObject, true)
        KTool.SetActive(object.transform.parent, true)
    end

    local render =  object.gameObject:GetComponent(typeof(ImageComp))
    if isNull(render) then
        return
    end
    self.PrevColor = render.color
    --render.color = self.Color
    self._isFinish = not self._isIn
    render.color = self.StartColor
    --printInfo(self.TargetColor)
    if self._isIn then
        self.Tween = render:DOColor(self.TargetColor, self.Duration):OnComplete(function()
            self._isFinish = true
        end)
    end
end

function FadeInScreenEffect:IsFinish()
    base.IsFinish(self)
    return self._isFinish
end

function FadeInScreenEffect:EndEffect(object)
    base.EndEffect(self, object)

end

function FadeInScreenEffect:RemoveEffect(object)
    base.RemoveEffect(self, object)

    local render =  object.gameObject:GetComponent(typeof(ImageComp))
    if isNull(render) then
        return
    end

    if not self._isIn then
        local co = cs_coroutine.start(function()
            local wait = true
            self.Tween = render:DOColor(self.TargetColor, self.Duration):OnComplete(function()
                wait = false
            end)

            while wait do
                coroutine.yield()
            end

            if KTool.IsActiveInHierarchy(object.gameObject) then
                KTool.SetActive(object.gameObject, false)
                KTool.SetActive(object.transform.parent, false)
            end

            render.color = self.PrevColor

        end)
        return co
    else
        if KTool.IsActiveInHierarchy(object.gameObject) then
            KTool.SetActive(object.gameObject, false)
            KTool.SetActive(object.transform.parent, false)
        end

        render.color = self.PrevColor

    end
end

return FadeInScreenEffect